import type { Plugin } from "@opencode-ai/plugin"

// ctx-wire OpenCode plugin - rewrites shell commands through ctx-wire so their
// output reaches the model with noise filtered and secrets scrubbed.
//
// Thin delegating plugin: all rewrite logic lives in `ctx-wire rewrite` (the
// single source of truth). Do not edit this file to change rules.
// Requires ctx-wire on PATH.
//
// OpenCode names its shell tool "shell" (older builds "bash") on every
// platform and picks the real shell at runtime: PowerShell (pwsh/powershell)
// on Windows, a POSIX sh on Unix. So the plugin detects the host itself: on
// win32 the line is PowerShell, where commands are mostly cmdlets (not
// executables) and default aliases shadow real programs (curl, ls, sort,
// where, ...). We ask the binary for its PowerShell recognizer via
// `--shell powershell`, which wraps only simple external commands and lets
// everything else pass through. If a Windows user configured git-bash as
// their opencode shell, that recognizer safely under-wraps rather than
// breaking.
const isPowerShell = process.platform === "win32"

export const CtxWireOpenCodePlugin: Plugin = async ({ $ }) => {
  try {
    await $`which ctx-wire`.quiet()
  } catch {
    console.warn("[ctx-wire] binary not found in PATH - plugin disabled")
    return {}
  }

  return {
    "tool.execute.before": async (input, output) => {
      const tool = String(input?.tool ?? "").toLowerCase()
      if (tool !== "bash" && tool !== "shell") return
      const args = output?.args
      if (!args || typeof args !== "object") return

      const command = (args as Record<string, unknown>).command
      if (typeof command !== "string" || !command) return

      try {
        const result = isPowerShell
          ? await $`ctx-wire rewrite --shell powershell --agent opencode ${command}`.quiet().nothrow()
          : await $`ctx-wire rewrite --agent opencode ${command}`.quiet().nothrow()
        const rewritten = String(result.stdout).trim()
        if (rewritten && rewritten !== command) {
          ;(args as Record<string, unknown>).command = rewritten
        }
      } catch {
        // ctx-wire rewrite failed - pass the command through unchanged.
      }
    },
  }
}
